function pullYardPart(id,di,pi,rush=false){const y=yardLocations.find(x=>x.id===id),d=(S.yardsData[id]||[])[di],p=d&&d.parts[pi],c=d&&cars.find(x=>x.id===d.carId);if(!y||!d||!p||!atYard(id)||!p.present||p.pulled)return;migrateYardAttempts(d);const slots=p.slots||1,remaining=S.yardTrip.capacity-S.yardTrip.used;if(slots>remaining){showModal(`<h2>It will not fit</h2><div class="card"><p>${yardPartName(p,c)} needs <b>${slots}</b> transport slots. You only have <b>${remaining}</b> left in the ${S.yardTrip.label}.</p></div><div class="modal-actions"><button onclick="openYardInventory('${id}',${di})">BACK</button></div>`);return}const pullHours=Math.max(.2,p.hours*(rush?.58:1));if(minuteOfDay()+Math.round(pullHours*60)>1140){openYardInventory(id,di);return}if(!p.scouted&&p.present===false){passTime(.15,true);openYardInventory(id,di);return}passTime(pullHours,true);const category=p.kind==='rare'?(p.template.type==='performance'?'Performance':p.template.type==='interior'?'Maintenance':'Bodywork'):(p.data.type==='performance'?'Performance':p.data.type==='engine'?'Engine':p.data.type==='body_panel'||p.data.type==='body'?'Bodywork':'Maintenance'),attempts=p.attempts||0,chance=clamp(chanceFor(p.req+attempts*4+(rush?8:0),rush?56:64,c.make,category),5,95);p.attempts=attempts+1;if(Math.random()*100<chance){if(S.cash<p.cost){addLog(`You get ${yardPartName(p,c)} loose, then realize you cannot pay the $${p.cost} checkout price. It stays with the donor.`,'bad');openYardInventory(id,di);render();return}let part;if(p.kind==='rare')part=cloneRarePart(p.template,`${y.name} - ${d.color} ${c.name}`,rand(28,78),Math.round(p.template.base*.55));else{const k=p.data,fitCarIds=k.fit==='car'?[c.id]:null,fitMakes=k.fit==='make'?[c.make]:null,def=p.panelKey?bodyPanelDefs.find(x=>x.id===p.panelKey):null;part={uid:`u-${Date.now()}-${Math.random()}`,name:`${c.name} ${def?def.name:k.name}`,type:k.type,fitCarIds,fitMakes,slots:p.slots||k.slots,style:k.style,perf:k.perf,value:Math.round(p.cost*2.1),condition:rand(30,82),panelKey:p.panelKey||null,color:p.panelColor||null,rarity:k.rarity||'COMMON',desc:`Pulled by you from a ${d.color} ${c.name} at ${y.name}. ${def?`Panel color is ${p.panelColor}.`:'No warranty. Obviously.'}`,source:y.name}}if(inventoryUsed()+part.slots>inventoryCapacity()&&S.location!=='parents'){addLog(`You successfully pull ${part.name}, then realize you have nowhere to store it at home. You leave it behind.`,'bad')}else{S.cash-=p.cost;S.usedParts.push(part);S.yardTrip.used+=part.slots;S.weekMetrics.junkPulls++;p.present=false;p.pulled=true;if(inventoryUsed()>inventoryCapacity()&&S.location==='parents'){const hit=rand(3,7);S.parentPatience=clamp(S.parentPatience-hit,0,100);addLog(`You are already over the garage storage limit and drag ${part.name} home anyway. Parent patience -${hit}.`,'warn')}gainExperience(c.make,category,2);addLog(`Junkyard win${rush?' (RUSHED)':''}: ${part.name} [${part.rarity||yardPartRarity(p)}] comes out for $${p.cost}. Condition about ${part.condition}%. Cargo ${S.yardTrip.used}/${S.yardTrip.capacity}.`,'good')}}else{const breakChance=clamp(.18+p.attempts*.18+(rush?.20:0),.22,.88);if(Math.random()<breakChance||p.attempts>=4){p.present=false;p.broken=true;addLog(`The ${yardPartName(p,c)} ${rush?'gets mangled while you rush':'finally loses the fight'} on attempt ${p.attempts}. It is broken / no longer worth pulling.`,'bad')}else{S.energy=clamp(S.energy-rand(2,7),0,100);addLog(`Attempt ${p.attempts} on ${yardPartName(p,c)} fails, but the part is still there. You can try again - the next attempt will be harder and more likely to break it.`,'warn')}maybeCreateLead(`what made the junkyard pull difficult`,c.make,category,.25)}openYardInventory(id,di);render()}

function isSwapOpen(){const wd=(dayNum()-1)%7,m=minuteOfDay();return (wd===2||wd===5)&&m>=480&&m<=900}
function nextSwapText(){const wd=(dayNum()-1)%7,candidates=[(2-wd+7)%7,(5-wd+7)%7].filter(d=>d>0),days=Math.min(...candidates);const target=(wd+days)%7===2?'Wednesday':'Saturday';return `in ${days} day${days===1?'':'s'} (${target}, 8:00 AM-3:00 PM)`}
function swapSessionKey(){return `${weekNum()}-${(dayNum()-1)%7}`}
function ensureSwapMeet(){const key=swapSessionKey();if(S.swapWeek===key&&S.swapListings.length)return;S.swapWeek=key;S.swapListings=[];const pool=[...marketplacePartTemplates],picked=new Set();for(let i=0;i<10&&pool.length;i++){let t=null;for(let tries=0;tries<40;tries++){const cand=pool[rand(0,pool.length-1)],key=cand.name.toLowerCase();const prefer=cand.rarity==='RARE'?.72:cand.rarity==='UNCOMMON'?.88:.32;if(!picked.has(key)&&Math.random()<prefer){t=cand;break}}if(!t)t=pool.find(x=>!picked.has(x.name.toLowerCase()))||pool[0];picked.add(t.name.toLowerCase());const condition=rand(38,96),price=Math.max(20,Math.round(t.base*(condition/100)*(.58+Math.random()*.50)/5)*5);S.swapListings.push({id:`sw-${weekNum()}-${i}-${Math.random()}`,part:cloneRarePart(t,'Swap Meet',condition,Math.round(t.base*condition/100)),price,sold:false,barterUsed:false,tradeUsed:false})}}
function openSwapMeet(){ensureSwapMeet();const open=isSwapOpen();showModal(`<h2>Wednesday + Saturday Swap Meet</h2><div class="card"><b>${open?'OPEN RIGHT NOW':'CLOSED'}</b><p>${open?'Rows of folding tables, trunks full of parts, wheels stacked everywhere. Cash is useful, but so are trades and a decent reputation.':'Next opening: '+nextSwapText()+'. You can hear what people plan to bring, but actual stock is not guaranteed until you show up.'}</p><p class="small">The meet now pulls from the same giant used-parts pool as Marketplace, with much better odds of uncommon / rare period pieces.</p></div><div class="modal-actions three"><button class="primary" onclick="attendSwapMeet()" ${open?'':'disabled'}>ATTEND / BROWSE</button><button onclick="openSellParts('swap',0)" ${open?'':'disabled'}>SELL YOUR PARTS</button><button onclick="openWorld()">BACK</button></div>`)}
function attendSwapMeet(){if(!isSwapOpen())return;const key=swapSessionKey();if(S.swapVisitedWeek!==key){S.swapVisitedWeek=key;if(S.startable&&S.driveable)driveTrip(14,.55,'Swap meet trip',true);else passTime(.8,true);passTime(.75,true);gainRep('scene',2);addLog('You spend part of the morning wandering the swap meet. Car Scene reputation +2.','good')}showSwapListing(0);render()}
function showSwapListing(index=0){swapIndex=clamp(index,0,S.swapListings.length-1);const l=S.swapListings[swapIndex],p=l.part;showModal(`<h2>Swap Meet Vendor</h2><div class="card"><div class="jobhead"><b>${p.name}</b><span class="rare">${p.rarity}</span></div><p>${p.desc}</p><div class="market-meta"><div><span>ASKING</span><b>$${l.price}</b></div><div><span>CONDITION</span><b>${p.condition}%</b></div><div><span>STYLE</span><b>+${p.style||0}</b></div><div><span>PERF</span><b>+${p.perf||0}</b></div></div><p>${listingFitText(p)}</p>${l.barterUsed?'<p class="small warntxt">You already tried a cash barter on this part.</p>':''}${l.tradeUsed?'<p class="small warntxt">You already floated a trade on this part.</p>':''}</div><div class="pager"><button onclick="showSwapListing(${swapIndex-1})" ${swapIndex===0?'disabled':''}>&lt;</button><span class="small">${swapIndex+1}/${S.swapListings.length}</span><button onclick="showSwapListing(${swapIndex+1})" ${swapIndex>=S.swapListings.length-1?'disabled':''}>&gt;</button></div><div class="modal-actions three"><button class="primary" onclick="buySwapPart('${l.id}')" ${(l.sold||S.cash<l.price||inventoryUsed()+p.slots>inventoryCapacity())?'disabled':''}>PAY $${l.price}</button><button onclick="openSwapBarter('${l.id}')" ${l.sold?'disabled':''}>BARTER / TRADE</button><button onclick="openSellParts('swap',0)">SELL PARTS</button></div><div class="modal-actions"><button onclick="openWorld()">LEAVE</button></div>`)}
function buySwapPart(id,priceOverride=null,note=''){const l=S.swapListings.find(x=>x.id===id);if(!l||l.sold)return;const price=priceOverride==null?l.price:priceOverride;if(S.cash<price||inventoryUsed()+l.part.slots>inventoryCapacity())return;S.cash-=price;S.usedParts.push(l.part);l.sold=true;S.weekMetrics.partsBought++;S.weekMetrics.swapDeals++;addLog(`Swap-meet score: ${l.part.name} for $${price}${note}.`,'good');showSwapListing(swapIndex);render()}
function openSwapBarter(id){const l=S.swapListings.find(x=>x.id===id);if(!l||l.sold)return;const trades=S.usedParts.length;showModal(`<h2>Barter - ${l.part.name}</h2><div class="card"><p>Vendor wants <b>$${l.price}</b>. You can make one cash pitch and one trade pitch before they stop entertaining you.</p><p class="small">Car Scene reputation helps. Lowballing is possible; annoying the vendor is also possible. You have ${trades} loose used/rare part${trades===1?'':'s'} that could be offered in trade.</p></div><div class="modal-actions three"><button onclick="makeSwapCashOffer('${id}',.85)" ${l.barterUsed?'disabled':''}>OFFER $${Math.round(l.price*.85/5)*5}</button><button onclick="makeSwapCashOffer('${id}',.70)" ${l.barterUsed?'disabled':''}>LOWBALL $${Math.round(l.price*.70/5)*5}</button><button onclick="openSwapTrade('${id}',0)" ${(!trades||l.tradeUsed)?'disabled':''}>OFFER A TRADE</button></div><div class="modal-actions"><button onclick="showSwapListing(swapIndex)">BACK</button></div>`)}
function makeSwapCashOffer(id,pct){const l=S.swapListings.find(x=>x.id===id);if(!l||l.sold||l.barterUsed)return;l.barterUsed=true;passTime(.08,true);const offer=Math.max(5,Math.round(l.price*pct/5)*5),rep=S.reputationChannels.scene||0,base=pct>=.85?62:24,chance=clamp(base+rep*.8,8,92);if(Math.random()*100<chance){addLog(`Swap-meet vendor takes your $${offer} offer on ${l.part.name}.`,'good');buySwapPart(id,offer,' after bartering')}else{if(Math.random()<.18)gainRep('scene',-1);addLog(`Swap-meet vendor turns down $${offer} for ${l.part.name}. "Nah. I can get more than that."`,'warn');showSwapListing(swapIndex);render()}}
function openSwapTrade(id,index=0){const l=S.swapListings.find(x=>x.id===id);if(!l||l.sold||l.tradeUsed)return;const arr=S.usedParts;if(!arr.length){openSwapBarter(id);return}index=clamp(index,0,arr.length-1);const p=arr[index],ratio=(p.value||20)/Math.max(1,l.price);showModal(`<h2>Offer a trade</h2><div class="card"><b>Your ${p.name}</b><p>Estimated value: <b>$${Math.round(p.value||20)}</b> / Condition ${p.condition||50}% / ${p.rarity||'USED'}</p><p class="small">Vendor ask: $${l.price}. Straight trades are judged on value, rarity, and whether the vendor thinks they can move your part. Scene rep helps a little.</p></div><div class="pager"><button onclick="openSwapTrade('${id}',${index-1})" ${index===0?'disabled':''}>&lt;</button><span class="small">${index+1}/${arr.length}</span><button onclick="openSwapTrade('${id}',${index+1})" ${index>=arr.length-1?'disabled':''}>&gt;</button></div><div class="modal-actions"><button class="primary" onclick="makeSwapTrade('${id}','${p.uid}')" ${(inventoryUsed()-(p.slots||1)+(l.part.slots||1)>inventoryCapacity())?'disabled':''}>OFFER STRAIGHT TRADE</button><button onclick="openSwapBarter('${id}')">BACK</button></div>`)}
function makeSwapTrade(id,uid){const l=S.swapListings.find(x=>x.id===id),p=S.usedParts.find(x=>x.uid===uid);if(!l||!p||l.sold||l.tradeUsed)return;l.tradeUsed=true;passTime(.12,true);const ratio=(p.value||20)/Math.max(1,l.price),rarityBonus=p.rarity==='RARE'?14:p.rarity==='UNCOMMON'?7:0,rep=(S.reputationChannels.scene||0)*.65,chance=clamp(18+ratio*52+rarityBonus+rep,6,94);if(Math.random()*100<chance){if(inventoryUsed()-(p.slots||1)+(l.part.slots||1)>inventoryCapacity()){showSwapListing(swapIndex);return}S.usedParts=S.usedParts.filter(x=>x.uid!==uid);S.usedParts.push(l.part);l.sold=true;S.weekMetrics.partsBought++;S.weekMetrics.partsSold++;S.weekMetrics.swapDeals++;gainRep('scene',1);addLog(`Swap-meet trade: your ${p.name} goes across the table and you come home with ${l.part.name}. No cash changed hands.`,'good');showSwapListing(swapIndex);render()}else{addLog(`Vendor looks at your ${p.name}, looks back at ${l.part.name}, and says no to the trade.`,'warn');showSwapListing(swapIndex);render()}}
function saleItems(){const out=[];for(const p of S.usedParts)out.push({kind:'used',uid:p.uid,name:p.name,value:p.value});for(const i of storeItems){const n=S.inventory[i.id]||0;if(n>0&&i.kind!=='tool')out.push({kind:'stock',id:i.id,name:i.name,value:i.price,count:n})}return out}
function openSellParts(venue='market',index=0){const arr=saleItems();sellIndex=clamp(index,0,Math.max(0,arr.length-1));if(!arr.length){showModal(`<h2>Sell Parts</h2><div class="card">You do not own anything you can sensibly sell right now.</div><div class="modal-actions"><button onclick="${venue==='swap'?'openSwapMeet()':'openWorld()'}">BACK</button></div>`);return}const x=arr[sellIndex],mult=venue==='swap'?(.85+Math.random()*.28):(.65+Math.random()*.30),offer=Math.max(5,Math.round(x.value*mult));showModal(`<h2>Sell Parts - ${venue==='swap'?'Swap Meet':'Marketplace'}</h2><div class="card"><b>${x.name}</b><p>${x.kind==='stock'?`You have ${x.count}.`: 'One used/rare part.'}</p><p>Likely buyer offer: <b>$${offer}</b></p><p class="small">${venue==='market'?'Marketplace pays worse and buyers can flake.':'Swap-meet buyers pay better because they are already standing in front of you.'}</p></div><div class="pager"><button onclick="openSellParts('${venue}',${sellIndex-1})" ${sellIndex===0?'disabled':''}>&lt;</button><span class="small">${sellIndex+1}/${arr.length}</span><button onclick="openSellParts('${venue}',${sellIndex+1})" ${sellIndex>=arr.length-1?'disabled':''}>&gt;</button></div><div class="modal-actions"><button class="primary" onclick="executePartSale('${venue}','${x.kind}','${x.uid||x.id}',${offer})">SELL FOR $${offer}</button><button onclick="${venue==='swap'?'openSwapMeet()':'openWorld()'}">BACK</button></div>`)}
function sellUsedPart(uid,venue='market'){const p=S.usedParts.find(x=>x.uid===uid);if(!p){openInventory();return}const mult=venue==='swap'?(.88+Math.random()*.18):(.68+Math.random()*.22),offer=Math.max(5,Math.round((p.value||20)*mult));showModal(`<h2>Sell ${p.name}?</h2><div class="card"><p>Likely ${venue==='swap'?'swap-meet':'Marketplace'} buyer price: <b>$${offer}</b>.</p><p class="small">Selling removes the loose part from garage storage immediately. Installed parts are never offered here.</p></div><div class="modal-actions"><button class="primary" onclick="executePartSale('${venue}','used','${p.uid}',${offer})">LIST / SELL FOR $${offer}</button><button onclick="showUsedInventory(Math.min(usedInvIndex,S.usedParts.length-1))">KEEP IT</button></div>`)}
function executePartSale(venue,kind,key,offer){if(venue==='market'){passTime(.35,true);if(Math.random()<.14){addLog('Your Marketplace buyer says they are on the way, then disappears forever.','warn');openSellParts(venue,sellIndex);render();return}}if(kind==='used')S.usedParts=S.usedParts.filter(x=>x.uid!==key);else S.inventory[key]=Math.max(0,(S.inventory[key]||0)-1);S.cash+=offer;S.weekMetrics.partsSold++;if(venue==='swap')S.weekMetrics.swapDeals++;addLog(`You sell a part for $${offer}${venue==='swap'?' at the swap meet':' through Marketplace'}.`,'good');openSellParts(venue,Math.max(0,sellIndex-1));render()}
function openStore(){const travel=S.startable&&S.driveable?'Driving to the parts store costs about 0.5h and 6 miles round trip.':'Your project cannot drive there. You can get a ride, but it costs about 1 hour.';showModal(`<h2>Parts Store</h2><div class="card"><b>Go to the store?</b><p>${travel}</p><p class="small">The store is now split into aisles. Some aisles unlock as your Knowledge / reputation grows.</p></div><div class="modal-actions"><button class="primary" onclick="travelToStore()">GO TO STORE</button><button onclick="closeModal()">BACK</button></div>`)}
function travelToStore(){if(S.startable&&S.driveable)driveTrip(6,.5,'Parts run');else{passTime(1,true);addLog('Someone gives you a ride to the parts store because your project is not moving.','warn')}storePage=0;showStoreAisles();render()}
function showStoreAisles(){storeView='aisles';const cards=storeAisles.map(a=>{const unlocked=a.unlock();const count=storeItems.filter(i=>i.aisle===a.id).length;return `<div class="aisle ${unlocked?'':'locked'}"><div class="jobhead"><b>${a.name}</b><span class="risk">${unlocked?`${count} ITEMS`:'LOCKED'}</span></div><p class="small">${a.desc}</p>${unlocked?`<button onclick="openStoreAisle('${a.id}')">ENTER AISLE</button>`:`<span class="small">Requires ${a.req}</span>`}</div>`}).join('');showModal(`<h2>Parts Store - Aisles</h2><div class="card"><b>Cash: $${S.cash}</b> &nbsp; Storage: <b>${inventoryUsed()} / ${inventoryCapacity()}</b><p class="small">Buying the wrong thing is still absolutely possible.</p></div><div class="aislegrid">${cards}</div><div class="modal-actions"><button onclick="confirmLeaveStore('aisles')">LEAVE STORE</button></div>`,'store')}
function confirmLeaveStore(from='aisles'){showModal(`<h2>Leave the parts store?</h2><div class="card"><p><b>Are you sure you want to leave?</b></p><p class="small">Nothing is lost, but this stops accidental exits while you are paging through aisles.</p></div><div class="modal-actions"><button class="danger" onclick="closeModal()">YES - LEAVE STORE</button><button onclick="${from==='aisle'?"showStorePage()":"showStoreAisles()"}">KEEP SHOPPING</button></div>`,'store')}
function openStoreAisle(id){const a=storeAisles.find(x=>x.id===id);if(!a||!a.unlock())return;storeAisle=id;storePage=0;showStorePage()}
function showStorePage(){storeView='aisle';const a=storeAisles.find(x=>x.id===storeAisle),items=storeItems.filter(i=>i.aisle===storeAisle),per=4,start=storePage*per,slice=items.slice(start,start+per),pages=Math.max(1,Math.ceil(items.length/per));let cards=slice.map(i=>{let hint='';if(S.knownProjectSpecs&&i.kind==='oil')hint=i.id===S.car.oil?'<span class="statusok">Correct for your project</span>':'<span class="small">Not your project oil spec</span>';if(S.knownProjectSpecs&&i.kind==='filter')hint=i.id===S.car.filter?'<span class="statusok">Correct for your project</span>':'<span class="small">Not your project filter</span>';const scannedNow=S.activeCodes?.length&&S.lastScanSignature===codeSignature(),matches=scannedNow&&i.dtcTags?S.activeCodes.filter(c=>i.dtcTags.includes(c.code)).map(c=>c.code):[];if(matches.length)hint+=`<br><span class="statusok">Possible match for ${matches.join(', ')}</span><br><span class="small">A DTC points at a system, not automatically this part.</span>`;if(i.kind==='tool')hint=`<span class="small">${i.bodyBonus?`Bodywork bonus: +${i.bodyBonus}`:`Mechanical skill bonus: +${i.toolBonus||0}`}${i.obdTier?` - OBD tier ${i.obdTier}`:''} ${S.inventory[i.id]?'[OWNED]':''}</span>`;const owned=S.inventory[i.id]||0,unique=i.kind==='tool',unlocked=!i.unlock||i.unlock();return `<div class="storeitem"><b>${i.name}</b><span>$${i.price}</span><div class="small">${i.desc||''}</div><div class="small">Owned: ${owned}</div><div>${hint}</div>${unlocked?`<button onclick="buyItem('${i.id}')" ${(unique&&owned)?'disabled':''}>${unique&&owned?'OWNED':'BUY'}</button>`:`<button disabled>LOCKED - ${i.req||'PROGRESSION'}</button>`}</div>`}).join('');showModal(`<h2>${a.name}</h2><div class="card"><b>Cash: $${S.cash}</b> &nbsp; Storage: <b>${inventoryUsed()} / ${inventoryCapacity()}</b>${storeAisle==='performance'?'<p class="small">Welcome to the aisle where reliability starts becoming negotiable.</p>':''}${storeAisle==='tuning'?'<p class="small">Tuning can help at race events later, but bad tuning should eventually be able to hurt the car.</p>':''}</div><div class="storegrid">${cards}</div><div class="pager"><button onclick="changeStore(-1)" ${storePage===0?'disabled':''}>&lt;</button><span class="small">Page ${storePage+1}/${pages}</span><button onclick="changeStore(1)" ${storePage>=pages-1?'disabled':''}>&gt;</button></div><div class="modal-actions"><button onclick="showStoreAisles()">BACK TO AISLES</button><button onclick="confirmLeaveStore('aisle')">LEAVE STORE</button></div>`,'store')}
function changeStore(n){const items=storeItems.filter(i=>i.aisle===storeAisle),pages=Math.max(1,Math.ceil(items.length/4));storePage=clamp(storePage+n,0,pages-1);showStorePage()}
function commitBuyItem(id,over=false){const i=item(id);S.cash-=i.price;S.inventory[id]=(S.inventory[id]||0)+1;if(i.kind==='tool'){const cat=i.bodyBonus?'Bodywork':'Maintenance';gainConfidence(S.car.make,cat,1);addLog(`New tool: ${i.name}. ${i.bodyBonus?`Bodywork tool bonus is now +${bodyToolBonus()}.`:`Mechanical tool bonus is now +${toolBonus()}.`}`,'good')}else if(over&&S.location==='parents'){const hit=rand(4,9);S.parentPatience=clamp(S.parentPatience-hit,0,100);addLog(`You cram ${i.name} into an already-full garage. Parent patience -${hit}.`,'warn')}else addLog(`Bought ${i.name} for $${i.price}.`,'good');if(i.obdTier&&S.activeCodes.length){render();showModal(`<h2>Scanner acquired - CEL is on</h2><div class="card"><p>Your ${S.car.name} currently has the check-engine light on.</p><p><b>${i.name}</b> can now read the actual diagnostic trouble code instead of leaving you to guess.</p></div><div class="modal-actions"><button class="primary" onclick="scanProjectCodes('store')">SCAN IT NOW</button><button onclick="showStorePage()">KEEP SHOPPING</button></div>`,'store');return}showStorePage();render()}
function buyItem(id){const i=item(id);if(i.kind==='tool'&&(S.inventory[id]||0)>0)return;if(S.cash<i.price){addLog(`You cannot afford ${i.name}.`,'warn');return}const after=inventoryUsed()+itemSlots(id);if(after>inventoryCapacity()){if(S.location==='parents'){showModal(`<h2>The garage is full</h2><div class="card"><p>Your parents already think there is too much car junk in here.</p><p><b>${i.name}</b> would put you at ${after} / ${inventoryCapacity()} slots.</p><p class="small">You can stash it anyway. That does not mean nobody will care.</p></div><div class="modal-actions"><button class="danger" onclick="commitBuyItem('${id}',true)">STASH IT ANYWAY</button><button onclick="showStorePage()">PUT IT BACK</button></div>`);return}showModal(`<h2>No room</h2><div class="card">${locations[S.location].name} only holds ${inventoryCapacity()} slots. You need to use parts, sell things later, or move somewhere bigger.</div><div class="modal-actions"><button onclick="showStorePage()">BACK</button></div>`);return}commitBuyItem(id,false)}

function taskNeeds(t){if(t.special==='oil')return {[S.car.oil]:1,[S.car.filter]:1};if(t.special==='dtc')return {};return t.needs||{}}
function taskAvailability(t){if(t.special==='dtc')return 'AVAILABLE';if(t.special==='inspect'&&S.lastBasicInspectDay===dayNum())return 'DONE TODAY';if(t.minKnowledge&&S.knowledge<t.minKnowledge)return `LOCKED - KNOWLEDGE ${t.minKnowledge}`;if(t.restoreMin&&S.progress<t.restoreMin)return `LOCKED - RESTORATION ${t.restoreMin}%`;if(t.requiresTool&&!(S.inventory[t.requiresTool]||0))return `NEEDS ${item(t.requiresTool)?.name||'SPECIAL TOOL'}`;if(t.minSkill&&((S.skillKnowledge[t.minSkill[0]]||0)<t.minSkill[1]))return `LOCKED - ${t.minSkill[0].toUpperCase()} ${t.minSkill[1]}`;return 'AVAILABLE'}

let bodyPanelIndex=0;
function openBodyExterior(index=0){bodyPanelIndex=clamp(index,0,bodyPanelDefs.length-1);recalcBody();const d=bodyPanelDefs[bodyPanelIndex],v=S.bodyPanels[d.id],color=(S.bodyPanelColors||{})[d.id]||S.paintColor,used=S.usedParts.filter(p=>p.type==='body_panel'&&p.panelKey===d.id&&usedPartFits(p)),heavy=v<48,minSkill=heavy?35:v<68?28:22,req=heavy?45:v<68?34:26,locked=(S.skillKnowledge.Bodywork||0)<minSkill;showModal(`<h2>Work on Project - Body / Exterior</h2><div class="card"><div class="market-meta"><div><span>BODY</span><b>${S.bodyCondition}%</b></div><div><span>PAINT</span><b>${S.paintColor}</b></div><div><span>MISMATCHED</span><b>${mismatchedPanelCount()}</b></div><div><span>APPEARANCE</span><b>${appearanceScore()}/100</b></div></div><p class="small">Cleaning is beginner-friendly. Sanding, filler, rust repair, primer and paint are not.</p></div><div class="card"><div class="jobhead"><b>${d.name}</b><span class="risk">${v}% - ${panelIssue(v).toUpperCase()}</span></div><p>Panel color: <b>${color}</b>${color!==S.paintColor?' <span class="warntxt">(mismatched)</span>':''}. Current condition: <b>${v}%</b>.</p><p class="small">${locked?`DIY restoration locked: Bodywork Knowledge ${S.skillKnowledge.Bodywork||0}/${minSkill}. You know enough to know sanding this right now is a bad idea.`:`DIY repair estimate: ${Math.round(bodyChance(req))}% success - ${bodyRisk(req)} - Body tools +${bodyToolBonus()}.`}</p></div><div class="pager"><button onclick="openBodyExterior(${bodyPanelIndex-1})" ${bodyPanelIndex===0?'disabled':''}>&lt;</button><span class="small">${bodyPanelIndex+1}/${bodyPanelDefs.length}</span><button onclick="openBodyExterior(${bodyPanelIndex+1})" ${bodyPanelIndex>=bodyPanelDefs.length-1?'disabled':''}>&gt;</button></div><div class="modal-actions four"><button onclick="studyBodyPanel()" ${S.lastBodyStudyDay===dayNum()?'disabled':''}>INSPECT / STUDY</button><button onclick="detailProject()" ${S.lastDetailDay===dayNum()?'disabled':''}>WASH / DETAIL</button><button onclick="attemptBodyRepair('${d.id}')" ${(v>=90||locked)?'disabled':''}>RESTORE PANEL</button><button onclick="chooseReplacementPanel('${d.id}')" ${used.length?'':'disabled'}>REPLACE (${used.length})</button></div><div class="modal-actions"><button onclick="showProjectWorkHub()">BACK TO PROJECT WORK</button></div>`)}
function studyBodyPanel(){if(S.lastBodyStudyDay===dayNum())return;S.lastBodyStudyDay=dayNum();passTime(.5,true);gainExperience(S.car.make,'Bodywork',1);const d=bodyPanelDefs[bodyPanelIndex];if(maybeCreateLead(`how to evaluate and repair the ${d.name.toLowerCase()} correctly`,S.car.make,'Bodywork',.78))addLog(`Looking closely at the ${d.name.toLowerCase()} gives you something specific to research instead of blindly sanding it.`,'good');else addLog(`You spend time inspecting gaps, paint, rust and previous repairs on the ${d.name.toLowerCase()}. You learn a little, but do not get a major breakthrough.`,'day');openBodyExterior(bodyPanelIndex);render()}
function detailProject(){const needs={detail_kit:1};if(!invHas(needs)){showMissingParts(needs,()=>openBodyExterior(bodyPanelIndex));return}consume(needs);passTime(1.5,true);garageNoiseCheck(.6);S.lastDetailDay=dayNum();S.cleanliness=100;S.weekMetrics.bodyJobs=(S.weekMetrics.bodyJobs||0)+1;gainExperience(S.car.make,'Bodywork',1);addLog(`You spend 1.5h washing, cleaning glass, polishing what still has clear coat, and making the ${S.car.name} look dramatically less neglected.`,'good');openBodyExterior(bodyPanelIndex);render()}
function attemptBodyRepair(panelKey){const d=bodyPanelDefs.find(x=>x.id===panelKey),v=S.bodyPanels[panelKey],heavy=v<48,minSkill=heavy?35:v<68?28:22,needs=heavy?{sandpaper_pack:1,body_filler:1,rust_converter:1,primer_can:1,paint_can:1,clear_coat:1}:{sandpaper_pack:1,body_filler:1,primer_can:1,paint_can:1,clear_coat:1},req=heavy?45:v<68?34:26,hours=heavy?6:v<68?4:2.5;if((S.skillKnowledge.Bodywork||0)<minSkill){showModal(`<h2>Not ready for this yet</h2><div class="card"><p>You are about to sand, reshape, prime and paint a real body panel. That is not an oil change.</p><p><b>Bodywork Knowledge ${S.skillKnowledge.Bodywork||0}/${minSkill}</b></p><p class="small">Inspect body damage, research actual bodywork leads, help with easier cosmetic work, and learn before risking the panel.</p></div><div class="modal-actions"><button onclick="openBodyExterior(${bodyPanelIndex})">BACK</button></div>`);return}if(!invHas(needs)){showMissingParts(needs,()=>openBodyExterior(bodyPanelIndex));return}showModal(`<h2>Restore ${d.name}?</h2><div class="card"><p>This will use <b>${needNames(needs)}</b> and about <b>${hours}h</b>.</p><p>Estimated success: <b>${Math.round(bodyChance(req))}%</b> - ${bodyRisk(req)}</p><p class="small">A successful driveway repair can still have an imperfect shade match. A bad one can make the panel uglier than when you started.</p></div><div class="modal-actions"><button class="primary" onclick="executeBodyRepair('${panelKey}',${req},${hours},${heavy})">TRY IT</button><button onclick="openBodyExterior(${bodyPanelIndex})">BACK</button></div>`)}
function executeBodyRepair(panelKey,req,hours,heavy){const d=bodyPanelDefs.find(x=>x.id===panelKey),needs=heavy?{sandpaper_pack:1,body_filler:1,rust_converter:1,primer_can:1,paint_can:1,clear_coat:1}:{sandpaper_pack:1,body_filler:1,primer_can:1,paint_can:1,clear_coat:1};consume(needs);passTime(hours,true);garageNoiseCheck(hours*.5);S.weekMetrics.bodyJobs=(S.weekMetrics.bodyJobs||0)+1;const before=S.bodyPanels[panelKey],success=Math.random()*100<bodyChance(req);if(success){const gain=heavy?rand(18,34):before<68?rand(12,24):rand(6,14),matchPenalty=Math.random()<(effectiveKnowledge(S.car.make,'Bodywork')<28?.28:.10)?rand(3,8):0;S.bodyPanels[panelKey]=clamp(before+gain-matchPenalty,0,96);S.bodyPanelColors[panelKey]=S.paintColor;recalcBody();S.progress=clamp(S.progress+Math.max(1,Math.round(gain/8)),0,100);gainExperience(S.car.make,'Bodywork',heavy?7:4);gainConfidence(S.car.make,'Bodywork',3);S.cleanliness=clamp(S.cleanliness-rand(6,14),0,100);addLog(`Bodywork win: the ${d.name.toLowerCase()} improves from ${before}% to ${S.bodyPanels[panelKey]}%.${matchPenalty?' The paint match is a little off, because driveway paint is driveway paint.':''}`,'good')}else{const loss=rand(3,11);S.bodyPanels[panelKey]=clamp(before-loss,10,100);recalcBody();loseConfidence(S.car.make,'Bodywork',4);S.cleanliness=clamp(S.cleanliness-rand(10,20),0,100);maybeCreateLead(`why the ${d.name.toLowerCase()} body repair went wrong`,S.car.make,'Bodywork',.85);addLog(`Bodywork FAIL: sanding/filler/paint gets away from you. The ${d.name.toLowerCase()} drops from ${before}% to ${S.bodyPanels[panelKey]}%. You now understand why paint shops charge money.`,'bad')}openBodyExterior(bodyPanelIndex);render()}
function chooseReplacementPanel(panelKey){const arr=S.usedParts.filter(p=>p.type==='body_panel'&&p.panelKey===panelKey&&usedPartFits(p));if(!arr.length){openBodyExterior(bodyPanelIndex);return}const p=arr[0];showModal(`<h2>Use replacement panel?</h2><div class="card"><b>${p.name}</b><p>Condition: ${p.condition}% - Source: ${p.source}</p><p class="small">Installing it takes about 2.2h. It may fit mechanically and still be the completely wrong color.</p></div><div class="modal-actions"><button class="primary" onclick="installUsedPart('${p.uid}')">INSTALL ON PROJECT</button><button onclick="openBodyExterior(${bodyPanelIndex})">BACK</button></div>`)}
function scannedDtcTasks(){if(!S.activeCodes?.length||S.lastScanSignature!==codeSignature())return [];return S.activeCodes.filter(c=>dtcCandidates(c.code).length).map(c=>({id:`dtc_${c.code}`,name:`CEL diagnosis / repair - ${c.code}`,category:c.category,req:18,hours:0,gain:0,rel:0,xp:0,special:'dtc',code:c.code,fail:'The code is still there.'}))}function visibleProjectTasks(){if(ftueActive()&&S.ftueStep===2)return projectTasks.filter(t=>t.id==='oil');const base=projectTasks.filter(t=>{if(t.id==='oil')return S.mileage>=S.nextOilDue-1000;if(t.id==='plugs')return S.mileage>=S.nextPlugDue-1000;if(t.special==='inspect')return S.lastBasicInspectDay!==dayNum();if(S.doneTasks[t.id])return false;if(t.prereq&&!S.doneTasks[t.prereq])return false;return true});return scannedDtcTasks().concat(base)}
function projectWork(){if(ftueActive()&&S.ftueStep===2){projectIndex=0;showProjectCard();return}showProjectWorkHub()}
function showProjectWorkHub(){const interior=S.usedParts.filter(p=>p.type==='interior'&&usedPartFits(p)).length,upgrades=S.usedParts.filter(p=>['wheels','performance','body'].includes(p.type)&&usedPartFits(p)).length,panels=S.usedParts.filter(p=>p.type==='body_panel'&&usedPartFits(p)).length;showModal(`<h2>Work on ${S.car.name}</h2><div class="card"><p>Pick what part of the project you are actually working on.</p><p class="small">Owned parts stay in inventory until you deliberately install them here.</p></div><div class="hubgrid"><div class="hubcard"><b>Mechanical / Service</b><p class="small">Maintenance, repairs, diagnosis-driven jobs and normal mechanical progression.</p><button onclick="openMechanicalWork()">OPEN</button></div><div class="hubcard"><b>Body / Exterior</b><p class="small">Panel condition, detailing, replacement panels and eventually real body restoration. ${panels} replacement panel${panels===1?'':'s'} fit.</p><button onclick="openBodyExterior(0)">OPEN</button></div><div class="hubcard"><b>Interior / Trim</b><p class="small">Seats, trim, steering wheels, head units and rare OEM interior pieces. ${interior} compatible part${interior===1?'':'s'} waiting.</p><button onclick="openProjectPartGroup('interior',0)">OPEN</button></div><div class="hubcard"><b>Owned Upgrades</b><p class="small">Wheels, exterior accessories and used performance parts you already bought or pulled. ${upgrades} compatible part${upgrades===1?'':'s'} waiting.</p><button onclick="openProjectPartGroup('upgrade',0)">OPEN</button></div></div><div class="modal-actions"><button onclick="closeModal()">CLOSE</button></div>`)}
function openMechanicalWork(){projectIndex=0;showProjectCard()}
function openProjectPartGroup(group,index=0){const types=group==='interior'?['interior']:['wheels','performance','body'],arr=S.usedParts.filter(p=>types.includes(p.type)&&usedPartFits(p));projectPartIndex=clamp(index,0,Math.max(0,arr.length-1));if(!arr.length){showModal(`<h2>${group==='interior'?'Interior / Trim':'Owned Upgrades'}</h2><div class="card"><p>You do not have any compatible owned parts in this section.</p><p class="small">Try Marketplace, a swap meet, or a Pull-A-Part yard.</p></div><div class="modal-actions"><button onclick="showProjectWorkHub()">BACK</button></div>`);return}const p=arr[projectPartIndex],canRefurb=group==='interior'&&p.condition<96;showModal(`<h2>Work on Project - ${group==='interior'?'Interior / Trim':'Owned Upgrades'}</h2><div class="card"><div class="jobhead"><b>${p.name}</b><span class="rare">${p.rarity||'USED'}</span></div><p>${p.desc||''}</p><div class="market-meta"><div><span>CONDITION</span><b>${p.condition}%</b></div><div><span>STYLE</span><b>+${p.style||0}</b></div><div><span>PERFORMANCE</span><b>+${p.perf||0}</b></div><div><span>SOURCE</span><b>${p.source||'USED'}</b></div></div>${group==='interior'?'<p class="small">Interior pieces can sometimes be cleaned, repaired or lightly refurbished before installation. Electronics are riskier than seats and plastic trim.</p>':''}</div><div class="pager"><button onclick="openProjectPartGroup('${group}',${projectPartIndex-1})" ${projectPartIndex===0?'disabled':''}>&lt;</button><span class="small">${projectPartIndex+1}/${arr.length}</span><button onclick="openProjectPartGroup('${group}',${projectPartIndex+1})" ${projectPartIndex>=arr.length-1?'disabled':''}>&gt;</button></div><div class="modal-actions three">${group==='interior'?`<button onclick="refurbishUsedPart('${p.uid}')" ${canRefurb?'':'disabled'}>${canRefurb?'REFURBISH / CLEAN':'ALREADY CLEAN'}<br><span class="small">~1.5h / $8-$18 supplies</span></button>`:''}<button class="primary" onclick="installUsedPart('${p.uid}')">INSTALL ON PROJECT</button><button onclick="showProjectWorkHub()">BACK</button></div>`)}
function refurbishUsedPart(uid){const p=S.usedParts.find(x=>x.uid===uid);if(!p||p.type!=='interior'||p.condition>=96)return;const electronic=/radio|head unit|stereo|amplifier|gauge|switch|clock/i.test(p.name),cat=electronic?'Electrical':'Bodywork',req=electronic?19:13,cost=rand(8,18);if(S.cash<cost){showModal(`<h2>Need cleaning / repair supplies</h2><div class="card">You need about <b>$${cost}</b> for cleaners, contact cleaner, small hardware or trim supplies.</div><div class="modal-actions"><button onclick="openProjectPartGroup('interior',projectPartIndex)">BACK</button></div>`);return}S.cash-=cost;passTime(1.5,true);const before=p.condition,chance=chanceFor(req,74,S.car.make,cat);if(Math.random()*100<chance){p.condition=clamp(before+rand(8,20),0,98);p.value=Math.round((p.value||25)*1.12);if(!p.refurbished&&p.condition>=75){p.style=(p.style||0)+1;p.refurbished=true}gainExperience(S.car.make,cat,electronic?2:1);gainConfidence(S.car.make,cat,1);addLog(`You refurbish ${p.name}: ${before}% -> ${p.condition}% condition.${p.refurbished?' It presents a little better now.':''}`,'good')}else{p.condition=clamp(before-rand(3,9),10,100);loseConfidence(S.car.make,cat,1);maybeCreateLead(`what went wrong refurbishing ${p.name}`,S.car.make,cat,.65);addLog(`Refurbishing ${p.name} goes sideways. Condition drops from ${before}% to ${p.condition}%.`,'warn')}openProjectPartGroup('interior',Math.min(projectPartIndex,S.usedParts.length-1));render()}

function showProjectCard(){const list=visibleProjectTasks(),tutorialOil=ftueActive()&&S.ftueStep===2;if(!list.length){showModal(`<h2>Work on your project</h2><div class="card"><p>Nothing routine is due and every currently known one-time job is finished.</p><p class="small">Drive it, diagnose new symptoms, research, or wait until service comes due.</p></div><div class="modal-actions"><button onclick="closeModal()">CLOSE</button></div>`);return}projectIndex=clamp(projectIndex,0,list.length-1);const t=list[projectIndex],needs=taskNeeds(t),status=taskAvailability(t),known=t.special!=='oil'||S.knownProjectSpecs,supplyText=t.special==='dtc'?'Choose a plausible repair after opening this job.':known?needNames(needs):'Oil/filter spec unknown. More knowledge may let you identify it.',disabled=status!=='AVAILABLE',timeDisplay=t.special==='dtc'?'VARIES':t.hours+'h',riskDisplay=t.special==='dtc'?'DIAGNOSIS':riskLabel(t.req,S.car.make,t.category),successDisplay=t.special==='dtc'?'PART-DEPENDENT':Math.round(chanceFor(t.req,62,S.car.make,t.category))+'%',dtcInfo=t.special==='dtc'?`<p class="small"><b>${t.code}</b> is scanned and active. The next screen shows plausible parts, not a guaranteed answer.</p>`:'';showModal(`<h2>${tutorialOil?'Step 3 - Do the oil change':'Work on your project'}</h2><div class="card">${tutorialOil?'<p><b>This is your first hands-on service.</b> Even an oil change consumes supplies, time and attention.</p>':''}<div class="jobhead"><b>${t.name}</b><span class="risk">${riskDisplay}</span></div><div class="kv"><div><span>TIME</span><b>${timeDisplay}</b></div><div><span>STATUS</span><b>${status}</b></div><div><span>SUCCESS</span><b>${successDisplay}</b></div></div><p><b>Supplies:</b> ${supplyText}</p>${dtcInfo}${t.id==='oil'?`<p class="small">Service appears here only within 1,000 miles of ${Math.round(S.nextOilDue).toLocaleString()} mi.</p>`:''}${t.id==='plugs'?`<p class="small">Plug service appears here only within 1,000 miles of ${Math.round(S.nextPlugDue).toLocaleString()} mi.</p>`:''}${t.requiresTool?`<p class="small"><b>Special tool:</b> ${item(t.requiresTool)?.name||t.requiresTool}${(S.inventory[t.requiresTool]||0)?' [OWNED]':' [REQUIRED]'}</p>`:''}${t.id==='timing'?'<p class="small">Timing service is still generic in this prototype. Later this becomes car-specific: belt vs chain, engine layout, and actual service difficulty.</p>':''}<p class="small">${confidenceRead(t.req,S.car.make,t.category)}</p></div><div class="pager"><button onclick="changeProject(-1)" ${tutorialOil?'disabled':''}>&lt;</button><span class="small">${projectIndex+1}/${list.length} - ${t.category}</span><button onclick="changeProject(1)" ${tutorialOil?'disabled':''}>&gt;</button></div><div class="modal-actions"><button class="primary" onclick="prepareProjectTask()" ${disabled?'disabled':''}>START JOB</button>${tutorialOil?'<button onclick="disableFtue()">SKIP DAY 1 GUIDE</button>':'<button onclick="closeModal()">CANCEL</button>'}</div>`)}
function changeProject(n){const list=visibleProjectTasks();if(!list.length)return;projectIndex=(projectIndex+n+list.length)%list.length;showProjectCard()}
function prepareProjectTask(){const list=visibleProjectTasks(),t=list[projectIndex];if(!t)return;if(t.special==='dtc'){openDtcRepairOptions(t.code);return}if(t.special==='oil'){showOilSelection(t);return}const needs=taskNeeds(t);if(!invHas(needs)){showMissingParts(needs,()=>showProjectCard());return}if(t.special==='inspect'){executeProjectTask(t,needs,null,'safe');return}promptProjectApproach(t,needs)}
function openDtcRepairOptions(code){const c=(S.activeCodes||[]).find(x=>x.code===code);if(!c)return showProjectWorkHub();const opts=dtcCandidates(code);if(!opts.length)return;ensureCelCause(c);const sc=bestScanner(),cards=opts.map(o=>{const it=item(o.itemId),owned=S.inventory[o.itemId]||0,chance=Math.round(chanceFor(o.req,68,S.car.make,c.category));return `<div class="storeitem"><b>${o.label}</b><span>$${it?.price||0}</span><div class="small">${it?.name||o.itemId}</div><div class="small">Owned: ${owned} - install chance about ${chance}%</div><button onclick="attemptDtcRepair('${code}','${o.itemId}')" ${owned?'':'disabled'}>${owned?'TRY THIS REPAIR':'NEED PART'}</button></div>`}).join('');showModal(`<h2>${code} - choose what to try</h2><div class="card"><b>${c.desc}</b><p>${scannerDetail(c,sc?.obdTier||1)}</p><p class="small">The hidden actual fault is not shown to you. You are choosing from plausible causes. Replacing the wrong part can be a perfectly successful installation that fixes absolutely nothing.</p></div><div class="storegrid">${cards}</div><div class="modal-actions three"><button onclick="storeAisle='engine';storePage=0;openStore()">GO TO PARTS STORE</button><button onclick="openMechanicalWork()">BACK TO WORK</button><button onclick="closeModal()">CANCEL</button></div>`)}
function attemptDtcRepair(code,itemId){const c=(S.activeCodes||[]).find(x=>x.code===code),opt=dtcCandidates(code).find(x=>x.itemId===itemId);if(!c||!opt||(S.inventory[itemId]||0)<1)return;const it=item(itemId),actual=ensureCelCause(c);S.inventory[itemId]--;passTime(opt.hours,true);garageNoiseCheck(opt.hours);const installOk=Math.random()*100<chanceFor(opt.req,68,S.car.make,c.category);if(!installOk){S.projectClues++;S.reliability-=rand(1,3);loseConfidence(S.car.make,c.category,2);maybeCreateLead(`${code} after a botched ${it?.name||'repair'} attempt`,S.car.make,c.category,.7);S.lastScanSignature='';addLog(`CEL repair attempt: installing ${it?.name||itemId} for ${code} goes badly. The code is unresolved and you created another problem to think about.`,'bad');closeModal();render();return}gainExperience(S.car.make,c.category,2);gainConfidence(S.car.make,c.category,1);const right=itemId===actual,clears=right&&Math.random()<.9;if(clears){S.activeCodes=S.activeCodes.filter(x=>x!==c);S.reliability=clamp(S.reliability+2,0,100);S.lastScanSignature='';addLog(`CEL repair success: ${it?.name||itemId} was actually related to ${code}. The fault does not return after the repair.`,'good');if(!S.activeCodes.length)addLog('The check-engine light is off. For now.','good')}else{S.projectClues++;S.lastScanSignature='';if(right){addLog(`You install ${it?.name||itemId} correctly and it was part of the ${code} problem, but the fault returns. There is more than one issue or the diagnosis is incomplete.`,'warn')}else{addLog(`You install ${it?.name||itemId} correctly. ${code} comes right back. Congratulations: successful parts-cannon practice.`,'warn')}maybeCreateLead(`${code} still present after trying ${it?.name||itemId}`,S.car.make,c.category,.82)}closeModal();render()}
function showMissingParts(needs,back){const missing={};for(const [id,n] of Object.entries(needs))if((S.inventory[id]||0)<n)missing[id]=n-(S.inventory[id]||0);if(ftueActive()&&S.ftueStep===2){showModal(`<h2>You need supplies first</h2><div class="card"><p>Missing: <b>${needNames(missing)}</b></p><p>Parts-store cost: about <b>$${needCost(missing)}</b>.</p><p class="small">For Day 1, the guide keeps you on the correct oil/filter so you learn the flow. After the tutorial, the full store will happily let you buy the wrong stuff.</p></div><div class="modal-actions"><button class="primary" onclick="ftueBuyOilSupplies()">GO BUY THE REQUIRED SUPPLIES</button><button onclick="disableFtue()">SKIP DAY 1 GUIDE</button></div>`);return}showModal(`<h2>You do not have the parts</h2><div class="card"><p>Missing: <b>${needNames(missing)}</b></p><p>Store price: about <b>$${needCost(missing)}</b></p></div><div class="modal-actions"><button onclick="openStore()">GO TO STORE</button><button id="backMissing">BACK</button></div>`);$('backMissing').onclick=back}
function ftueBuyOilSupplies(){if(!ftueActive()||S.ftueStep!==2)return;const needs={[S.car.oil]:1,[S.car.filter]:1},missing={};for(const [id,n] of Object.entries(needs))if((S.inventory[id]||0)<n)missing[id]=n-(S.inventory[id]||0);const cost=needCost(missing);if(S.cash<cost)return;S.cash-=cost;if(S.startable&&S.driveable)driveTrip(6,.5,'Day 1 parts-store run',false);else passTime(1,true);for(const [id,n] of Object.entries(missing))S.inventory[id]=(S.inventory[id]||0)+n;addLog(`You make a guided parts-store run and spend $${cost} on the correct oil-service supplies. Later, the store will not protect you from bad purchases.`,'day');showOilSelection(projectTasks.find(t=>t.id==='oil'));render()}
function ownedByKind(kind){return storeItems.filter(i=>i.kind===kind&&(S.inventory[i.id]||0)>0)}function showOilSelection(t){const oils=ownedByKind('oil'),filters=ownedByKind('filter');if(!oils.length||!filters.length||!(S.inventory[S.car.oil]||0)||!(S.inventory[S.car.filter]||0)){showMissingParts({[S.car.oil]:1,[S.car.filter]:1},()=>showProjectCard());return}const hints=S.knownProjectSpecs;S.pendingOil={task:t,oil:null,filter:null};if(ftueActive()&&S.ftueStep===2){const oi=item(S.car.oil);showModal(`<h2>Oil change - choose the oil</h2><div class="card"><p>You checked the cap/manual during your research. For this first service, the guide only exposes the known-correct choice.</p></div><div class="modal-actions"><button class="primary" onclick="chooseOil('${S.car.oil}')">${oi.name} [CORRECT]</button><button onclick="disableFtue()">SKIP DAY 1 GUIDE</button></div>`);return}const oilBtns=oils.map(i=>`<button onclick="chooseOil('${i.id}')">${i.name}${hints&&i.id===S.car.oil?' [CORRECT]':''}</button>`).join('');showModal(`<h2>Oil change - choose oil</h2><div class="card"><p class="small">${hints?'You checked the cap/manual. Correct choices are marked.':'You are still working from whatever you think you remember.'}</p></div><div class="modal-actions">${oilBtns}<button onclick="openStore()">GO TO STORE</button><button onclick="showProjectCard()">BACK</button></div>`)}
function chooseOil(id){S.pendingOil.oil=id;const filters=ownedByKind('filter'),hints=S.knownProjectSpecs;if(ftueActive()&&S.ftueStep===2){const fi=item(S.car.filter);showModal(`<h2>Oil change - choose the filter</h2><div class="card"><b>Selected oil:</b> ${item(id).name}<p class="small">Same lesson: fitment matters. The Day 1 guide keeps you on the correct filter.</p></div><div class="modal-actions"><button class="primary" onclick="finishOilSelection('${S.car.filter}')">${fi.name} [CORRECT]</button><button onclick="disableFtue()">SKIP DAY 1 GUIDE</button></div>`);return}const btns=filters.map(i=>`<button onclick="finishOilSelection('${i.id}')">${i.name}${hints&&i.id===S.car.filter?' [CORRECT]':''}</button>`).join('');showModal(`<h2>Oil change - choose filter</h2><div class="card"><b>Selected oil:</b> ${item(id).name}</div><div class="modal-actions">${btns}<button onclick="openStore()">GO TO STORE</button><button onclick="showOilSelection(S.pendingOil.task)">BACK</button></div>`)}function finishOilSelection(filterId){const p=S.pendingOil;p.filter=filterId;promptProjectApproach(p.task,{[p.oil]:1,[p.filter]:1},{oil:p.oil,filter:p.filter})}
function promptProjectApproach(t,needs,selection=null){pendingProjectApproach={task:t,needs,selection};const safeExtra=t.req>=45?1.5:t.req>=25?1:.5,safeChance=Math.round(chanceFor(t.req,72,S.car.make,t.category)),riskChance=Math.round(chanceFor(t.req,57,S.car.make,t.category));showModal(`<h2>How are you approaching ${t.name}?</h2><div class="card"><p>This is the decision before the wrenching starts.</p><div class="kv"><div><span>SAFE ROUTE</span><b>${safeChance}%</b><span class="small">+${safeExtra}h prep</span></div><div><span>RISK IT</span><b>${riskChance}%</b><span class="small">No prep time</span></div><div><span>DIFFICULTY</span><b>${t.req}</b><span class="small">${riskLabel(t.req,S.car.make,t.category)}</span></div></div><p class="small"><b>Safe route:</b> check procedure, lay out tools, inspect fasteners and verify what you are doing. <b>Risk it:</b> save time, trust yourself, and accept a nastier failure if you are wrong.</p></div><div class="modal-actions three"><button class="good" onclick="startProjectApproach('safe')">TAKE THE SAFE ROUTE</button><button class="danger" onclick="startProjectApproach('risk')">RISK IT / SEND IT</button><button onclick="showProjectCard()">BACK OUT</button></div>`)}
function startProjectApproach(mode){const p=pendingProjectApproach;if(!p)return;const t=p.task;if(mode==='safe'){const extra=t.req>=45?1.5:t.req>=25?1:.5;passTime(extra,true);garageNoiseCheck(extra);addLog(`You spend ${extra}h checking the procedure and laying everything out before touching the ${t.name.toLowerCase()}.`,'day')}else addLog(`You decide to save time and just send the ${t.name.toLowerCase()} job.`, 'warn');executeProjectTask(t,p.needs,p.selection,mode)}
function projectSuccessRep(t){if(t.special==='inspect'||t.id==='oil')return;const work=t.req>=45?2:t.req>=20?1:0;if(work)gainRep('workmanship',work);if(t.perfGain)gainRep('scene',1)}
function executeProjectTask(t,needs,selection=null,approach='normal'){consume(needs);passTime(t.hours,true);garageNoiseCheck(t.hours);closeModal();if(t.special==='inspect'){runBasicInspection();return}const baseChance=approach==='safe'?72:approach==='risk'?57:62,success=Math.random()*100<chanceFor(t.req,baseChance,S.car.make,t.category);if(t.id==='oil')ftueAdvance(2,'You just did your first real service job. Even simple work costs time, supplies and carries some chance of going wrong. The project also needs money, so go earn some.');if(success){S.weekMetrics.projectSuccess++;S.progress+=t.gain;S.reliability+=t.rel;if(t.perfGain)S.performanceScore=clamp((S.performanceScore||0)+t.perfGain,0,100);gainExperience(S.car.make,t.category,t.xp);gainConfidence(S.car.make,t.category,rand(2,4)+(approach==='risk'?1:0));projectSuccessRep(t);if(t.id==='oil'){const right=selection&&selection.oil===S.car.oil&&selection.filter===S.car.filter;if(right){S.nextOilDue=S.mileage+3000;S.doneTasks.oil=false;addLog(`Oil service completed correctly. Next service around ${Math.round(S.nextOilDue).toLocaleString()} mi.`,'good')}else{S.reliability-=8;loseConfidence(S.car.make,'Maintenance',3);S.nextOilDue=S.mileage+300;S.projectClues++;addLog('The oil change is complete, but you used something that does not match the car. That is now a real thing worth diagnosing later.','bad')}}else if(t.id==='plugs'){S.nextPlugDue=S.mileage+30000;S.doneTasks.plugs=false;addLog(`Spark plugs completed. They will not show as routine service again until you are within 1,000 miles of roughly ${Math.round(S.nextPlugDue).toLocaleString()} mi.`,'good')}else{S.doneTasks[t.id]=true;addLog(`Project win: ${t.name} completed in ${t.hours}h. Hands-on experience improves; a successful repair does not automatically invent a new symptom.`,'good')}if(t.id==='starter'||t.id==='timing')S.startable=true;if(['clutch','bearing','brakes'].includes(t.id))S.driveable=true;if(S.activeCodes.length&&['plugs','starter','timing','head'].includes(t.id)&&Math.random()<.45){const cleared=S.activeCodes.shift();S.lastScanSignature='';addLog(`After the repair, the ${cleared.code} fault does not immediately return.`,'good')}if(t.id==='headers')maybeCreateLead('fueling and tuning after changing engine airflow',S.car.make,'Tuning',.58);else if(t.id==='injectors')maybeCreateLead('fuel trims and injector scaling',S.car.make,'Tuning',.72);else if(t.req>=30)maybeCreateLead(`a detail you learned during the ${t.name.toLowerCase()}`,S.car.make,t.category,.12);else maybeCreateLead(`a detail you learned during the ${t.name.toLowerCase()}`,S.car.make,t.category,.06);maybeNonsense();render();return}S.weekMetrics.projectFail++;S.projectClues++;pendingFailure={task:t,selection,approach};loseConfidence(S.car.make,t.category,approach==='risk'?5:3);if(approach==='risk')S.reliability-=rand(1,3);if(Math.random()<.35)addRandomCel('the failed repair');maybeCreateLead(`why the ${t.name.toLowerCase()} went wrong`,S.car.make,t.category,.72);showFailureDecision(t)}
function showFailureDecision(t){const risk=['timing','head','plugs'].includes(t.id)?'Starting the car after this could make things worse.':'The job is not finished, but you have not necessarily destroyed anything yet.',approach=pendingFailure?.approach==='risk'?'You chose the risky route, so the margin for recovery is smaller.':'You took the safer route, which may have limited how bad the mistake became.';showModal(`<h2>${t.name} did not go to plan</h2><div class="card"><p class="badtxt"><b>${t.fail}</b></p><p>${risk}</p><p class="warntxt">${approach}</p><p class="small">Failure does not automatically give Knowledge. You may get a research lead, but it could also be bad information.</p></div><div class="modal-actions"><button onclick="resolveFailure('stop')">STOP AND LEAVE IT</button><button class="danger" onclick="resolveFailure('risk')">RISK IT AND TRY TO FIX IT</button></div>`)}
function resolveFailure(action){const t=pendingFailure.task;if(action==='stop'){loseConfidence(S.car.make,t.category,2);applyFailureState(t,false);addLog(`You stop on the ${t.name.toLowerCase()} before forcing the issue.`,'warn');showPostFailureStart(t);return}const extra=Math.max(.5,Math.min(2,t.hours*.25));passTime(extra,true);const rescuePenalty=pendingFailure?.approach==='risk'?12:6,rescue=Math.random()*100<chanceFor(t.req+rescuePenalty,pendingFailure?.approach==='safe'?58:50,S.car.make,t.category);if(rescue){gainConfidence(S.car.make,t.category,2);S.reliability+=1;addLog(`You slow down and get the sketchy part of the ${t.name.toLowerCase()} back under control. (+${extra}h)`,'good')}else{loseConfidence(S.car.make,t.category,5);S.reliability-=rand(2,6);applyFailureState(t,true);addLog(`You push your luck on the ${t.name.toLowerCase()} and make the situation worse. (+${extra}h)`,'bad')}showPostFailureStart(t)}
